package client

import (
	"agenterm/internal/i18n"
	"agenterm/internal/protocol"
	"bytes"
	"context"
	"crypto/rand"
	"encoding/hex"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
	"sync"
	"time"
)

// A terminal owns the shell; each command has a separate lifecycle. Prompt
// frames carry the real shell exit status, including after a foreground SIGINT.
// They are generated by our shell integration, never inferred from visible text.
type persistentTerminal struct {
	submitted chan struct{}
	c         *connection
	p         *process
	id        string
	mu        sync.Mutex
	active    *CommandEvent
	reserved  bool

	persistent        bool
	promoted          bool
	retentionTimer    *time.Timer
	retentionDeadline time.Time
	autoClosed        bool
	lastExitCode      int
	ready             chan struct{}
	readyOnce         sync.Once
	dir               string
	marker            string
	closed            bool
}

// Terminal selection and lifetime belong to the client, never its server cache.
func (c *connection) runPersistent(m protocol.Message) {
	reject := func(err error) {
		_ = c.send(protocol.Message{Type: "command_rejected", ID: m.ID, RequestID: m.RequestID, Error: err.Error()})
	}
	if m.Cwd != "" || len(m.Env) > 0 {
		reject(i18n.NewError("session.options.require.setup"))
		return
	}
	if err := protocol.ValidateSessionRequest(m.SessionID, m.Setup); err != nil {
		reject(err)
		return
	}
	if m.WaitMS < 0 || m.WaitMS > 20000 {
		reject(i18n.NewError("session.read.invalid.arguments"))
		return
	}
	c.mu.Lock()
	id := m.SessionID
	if m.Setup != nil {
		id = m.Setup.SessionID
	}
	p := c.running[id]
	if m.Setup != nil && p != nil {
		c.mu.Unlock()
		reject(i18n.NewError("session.already.exists", id))
		return
	}
	if m.SessionID != "" && p == nil {
		c.mu.Unlock()
		reject(i18n.NewError("unknown.session"))
		return
	}
	var startCtx context.Context
	created := false
	if p == nil {
		if !acquireTerminalSlot() {
			c.mu.Unlock()
			reject(i18n.NewError("session.limit.reached.try.again.later"))
			return
		}
		ctx, cancel := context.WithCancel(context.Background())
		p = &process{cancel: cancel, ready: make(chan struct{}), inputQueue: make(chan protocol.Message, 32), ownsTerminalSlot: true}
		// Keep the private prompt marker independent of the public session ID.
		nonce := make([]byte, 27)
		for {
			if _, err := rand.Read(nonce); err != nil {
				c.mu.Unlock()
				cancel()
				p.releaseTerminalSlot()
				reject(err)
				return
			}
			if id != "" {
				break
			}
			candidate := hex.EncodeToString(nonce[24:])
			if c.running[candidate] == nil {
				id = candidate
				break
			}
		}
		markerID := hex.EncodeToString(nonce[:24])
		t := &persistentTerminal{c: c, p: p, id: id, ready: make(chan struct{}), marker: "\x1eagenterm:" + markerID + ":", submitted: make(chan struct{}), reserved: true, persistent: (m.Setup != nil && m.Setup.SessionID != "") || m.WaitMS == 0, promoted: (m.Setup == nil || m.Setup.SessionID == "") && m.WaitMS == 0}
		p.terminal = t
		c.running[id] = p
		created, startCtx = true, ctx
	} else {
		t := p.terminal
		if t == nil {
			c.mu.Unlock()
			reject(i18n.NewError("session.already.ended"))
			return
		}
		t.mu.Lock()
		var err error
		switch {
		case t.closed:
			err = i18n.NewError("session.already.ended")
		case !t.persistent || t.reserved || t.active != nil:
			err = i18n.NewError("session.busy", id)
		}
		if err != nil {
			t.mu.Unlock()
			c.mu.Unlock()
			reject(err)
			return
		}
		t.reserved = true
		t.submitted = make(chan struct{})
		t.mu.Unlock()
	}
	t := p.terminal
	c.mu.Unlock()
	ack := protocol.Message{Type: "command_accepted", ID: m.ID, RequestID: m.RequestID, SessionID: id, SessionCreate: created, Command: m.Command}
	t.mu.Lock()
	t.lifecycleLocked(&ack)
	t.mu.Unlock()
	if c.send(ack) != nil {
		p.stop()
		if created {
			c.mu.Lock()
			delete(c.running, id)
			c.mu.Unlock()
			p.releaseTerminalSlot()
		}
		return
	}
	// Start only after admission has been sent, so the server binds its cache
	// before any promotion or output can arrive.
	t.mu.Lock()
	if created && !t.persistent {
		t.retentionDeadline = time.Now().Add(time.Duration(m.WaitMS) * time.Millisecond)
		t.retentionTimer = time.AfterFunc(time.Until(t.retentionDeadline), func() { t.retain(m.RequestID) })
	}
	t.mu.Unlock()
	if created {
		c.workers.Add(2)
		go c.inputWorker(startCtx, p)
		go t.serve(startCtx, m)
	}
	c.workers.Add(1)
	go func() { defer c.workers.Done(); t.execute(m) }()
}

func (t *persistentTerminal) serve(ctx context.Context, first protocol.Message) {
	defer t.c.workers.Done()
	defer t.p.releaseTerminalSlot()
	defer func() {
		t.p.stop()
		if t.dir != "" {
			_ = os.RemoveAll(t.dir)
		}
	}()
	stopIO := context.AfterFunc(ctx, t.p.stop)
	defer stopIO()
	var cmd *exec.Cmd
	var err error
	t.dir, err = os.MkdirTemp("", "agenterm-shell-")
	if err == nil {
		options := protocol.ExecOptions{}
		if first.Setup != nil {
			options = first.Setup.ExecOptions
		}
		cmd = persistentShellCommand(ctx, t.marker, options)
		configureCommand(cmd, true)
		var input io.WriteCloser
		var output io.ReadCloser
		input, output, err = startPersistentInteractive(cmd)
		if err == nil {
			t.p.setIO(input, output)
			if line := persistentInitLine(t.marker); line != "" {
				if err = t.p.write(line); err != nil {
					t.p.stop()
				}
			}
			frames := &promptFrames{prefix: []byte(t.marker), output: t.output, complete: t.prompt}
			writer := newOutputWriter(frames)
			_, _ = io.Copy(writer, output)
			_ = writer.Close()
			frames.flush()
			err = cmd.Wait()
		}
	}
	code, detail := processResult(cmd, err)
	t.mu.Lock()
	t.closed = true
	t.stopRetentionTimerLocked()
	canceled := ctx.Err() != nil
	if t.autoClosed {
		code, detail, canceled = t.lastExitCode, "", false
	} else if canceled {
		code, detail = -1, i18n.Text(i18n.Terminal(), "execution.canceled")
	}
	t.finishLocked(code, detail, canceled, false)
	t.readyOnce.Do(func() { close(t.ready) })
	select {
	case <-t.submitted:
	default:
		close(t.submitted)
	}
	done := protocol.Message{Type: "done", ID: t.id, ExitCode: code, Error: detail, Canceled: canceled}
	t.lifecycleLocked(&done)
	t.mu.Unlock()
	// Release before confirming termination so a replacement can start as soon
	// as the server receives done. Startup failures release their reservation too.
	t.p.stop()
	t.p.releaseTerminalSlot()
	// Serialize removal and the final event with new admissions of this ID.
	// This keeps an old shell's done from arriving after its replacement's ACK.
	t.c.mu.Lock()
	if t.c.running[t.id] == t.p {
		delete(t.c.running, t.id)
	}
	_ = t.c.send(done)
	t.c.mu.Unlock()
}

func (t *persistentTerminal) execute(m protocol.Message) {
	// Startup must complete before the first command; its prompt is not a
	// completion of the submitted command. Startup has its own bounded wait.
	select {
	case <-t.ready:
	case <-time.After(10 * time.Second):
		t.p.stop()
		return
	}
	t.mu.Lock()
	if t.closed {
		t.mu.Unlock()
		return
	}
	eventMessage := m
	eventMessage.ID, eventMessage.Interactive = m.RequestID, true
	event := t.c.commandStarted(eventMessage)
	t.active = &event
	t.reserved = false
	line, err := persistentCommandLine(t.dir, m.Command)
	t.mu.Unlock()
	if err == nil {
		err = t.p.write(line)
	}
	if err != nil {
		t.p.stop()
	}
	t.mu.Lock()
	select {
	case <-t.submitted:
	default:
		close(t.submitted)
	}
	t.mu.Unlock()
}

func (t *persistentTerminal) waitSubmitted(ctx context.Context) error {
	t.mu.Lock()
	gate := t.submitted
	t.mu.Unlock()
	select {
	case <-gate:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func (t *persistentTerminal) prompt(code int) {
	t.mu.Lock()
	defer t.mu.Unlock()
	t.readyOnce.Do(func() { close(t.ready) })
	t.finishLocked(code, "", false, true)
}

func (t *persistentTerminal) finishLocked(code int, detail string, canceled, notify bool) {
	if t.active == nil {
		return
	}
	event := *t.active
	// A delayed timer goroutine must not turn a command that exceeded the
	// deadline into a one-shot success. Check the clock under the same lock.
	if !t.retentionDeadline.IsZero() && !time.Now().Before(t.retentionDeadline) {
		t.retainLocked(event.ID)
	}
	t.active = nil
	t.lastExitCode = code
	autoClose := !t.persistent && !t.closed
	if autoClose {
		t.closed, t.autoClosed = true, true
		t.stopRetentionTimerLocked()
	}
	t.c.commandFinished(event, code, detail)
	if notify {
		m := protocol.Message{Type: "command_done", ID: t.id, RequestID: event.ID, ExitCode: code, Error: detail, Canceled: canceled}
		t.lifecycleLocked(&m)
		_ = t.c.send(m)
	}
	if autoClose {
		t.p.stop()
	}
}

func (t *persistentTerminal) output(data []byte) error {
	// Discard only startup chatter before the integration is ready.
	select {
	case <-t.ready:
	default:
		return nil
	}
	t.mu.Lock()
	id := ""
	if t.active != nil {
		id = t.active.ID
	}
	t.mu.Unlock()
	return t.c.forwardOutput(protocol.Message{Type: "output", ID: t.id, RequestID: id, Stream: "terminal"}, id, data)
}

// Prompt framing is incremental: a frame or UTF-8 character may span reads.
// Only our random prefix followed by an integer and the terminator is removed.
type promptFrames struct {
	prefix   []byte
	pending  []byte
	output   func([]byte) error
	complete func(int)
}

func (f *promptFrames) Write(data []byte) (int, error) {
	f.pending = append(f.pending, data...)
	for len(f.pending) > 0 {
		i := bytes.Index(f.pending, f.prefix)
		if i < 0 {
			n := len(f.pending)
			for k := min(n, len(f.prefix)-1); k > 0; k-- {
				if bytes.Equal(f.pending[n-k:], f.prefix[:k]) {
					n -= k
					break
				}
			}
			if n > 0 {
				if err := f.output(f.pending[:n]); err != nil {
					return 0, err
				}
				f.pending = f.pending[n:]
			}
			break
		}
		if i > 0 {
			if err := f.output(f.pending[:i]); err != nil {
				return 0, err
			}
			f.pending = f.pending[i:]
		}
		end := bytes.IndexByte(f.pending[len(f.prefix):], '\x1f')
		if end < 0 {
			if len(f.pending) <= len(f.prefix)+16 {
				break
			}
			if err := f.output(f.pending[:1]); err != nil {
				return 0, err
			}
			f.pending = f.pending[1:]
			continue
		}
		end += len(f.prefix)
		code, err := strconv.Atoi(string(f.pending[len(f.prefix):end]))
		if err != nil {
			if err := f.output(f.pending[:1]); err != nil {
				return 0, err
			}
			f.pending = f.pending[1:]
			continue
		}
		f.pending = f.pending[end+1:]
		f.complete(code)
	}
	return len(data), nil
}

func (f *promptFrames) flush() {
	if len(f.pending) > 0 {
		_ = f.output(f.pending)
		f.pending = nil
	}
}

func shellQuote(value string) string { return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'" }

func writeCommandScript(dir, command, extension string) (string, error) {
	// The script is sourced in the shell, preserving cd/export/functions. Sending
	// a single source line prevents multiline commands from consuming queued
	// protocol text as interactive program input.
	path := filepath.Join(dir, "command"+extension)
	return path, os.WriteFile(path, []byte(command+"\n"), 0600)
}
